-- GÉNÉRÉ — Refonte des équipes staff : Staff Guide / Staff Narration + options, fin du pôle Bâtisseur.
alter table recrutement.postes add column if not exists options jsonb not null default '[]';
delete from recrutement.postes where categorie = 'staff';
delete from recrutement.groupes where id = 'batisseur';
insert into recrutement.postes (categorie,groupe,nom,description,missions,anciennete,disponibilite,note_candidat,statut,places_total,places_dispo,questions,options,ordre) values ('staff',$s$guide$s$,$s$Staff Guide$s$,$s$Aider, accompagner et animer : le visage du serveur pour les membres.$s$,array[$s$Aider et accompagner les membres$s$,$s$Créer des animations$s$,$s$Lire et accepter les questionnaires d'entrée$s$,$s$Gérer les conflits et les tickets$s$]::text[],$s$1 à 2 mois sur le serveur$s$,$s$5h / semaine minimum$s$,$s$Les options sont facultatives : tu peux candidater au rôle sans en choisir.$s$,'ouvert',3,3,$j$[{"id":"q1","label":"Comment accueillerais-tu un nouveau membre perdu ?","type":"textarea","min":30,"required":true},{"id":"q2","label":"Comment gères-tu un ticket urgent quand tu es occupé·e ?","type":"textarea","min":30,"required":true},{"id":"q3","label":"Deux membres s'opposent dans un salon et la tension monte. Comment gères-tu ce conflit ?","type":"textarea","min":30,"required":true},{"id":"q4","label":"Un questionnaire d'entrée est incomplet ou limite. Comment décides-tu, et que réponds-tu au candidat ?","type":"textarea","min":30,"required":true},{"id":"q5","label":"Propose une idée d’animation pour le serveur.","type":"textarea","min":30,"required":true}]$j$::jsonb,$j$[{"id":"regisseur","nom":"Régisseur·se de fiche","description":"Correction des fiches de personnage.","missions":["Lecture et correction des fiches de personnage soumises","Vérification de la cohérence avec les règles du serveur (noms, rangs, génétique)","Retours bienveillants et guidage des membres lors des corrections"],"places_total":2,"places_dispo":2,"membres":[],"questions":[{"id":"q1","label":"Comment vérifies-tu la cohérence d'une fiche avec les règles du serveur ?","type":"textarea","min":30,"required":true},{"id":"q2","label":"Comment formules-tu un retour de correction sans décourager le membre ?","type":"textarea","min":30,"required":true},{"id":"q3","label":"Un membre conteste ta correction — comment réagis-tu ?","type":"textarea","min":30,"required":true}]},{"id":"geneticien","nom":"Généticien·ne","description":"Correction génétique des personnages.","missions":["Traitement des demandes de génétique (pelages, yeux, traits hérités)","Gestion et mise à jour du registre génétique du serveur","Accompagnement des membres sur les questions génétiques complexes"],"places_total":1,"places_dispo":1,"membres":[],"questions":[{"id":"q1","label":"Explique le fonctionnement de l'hérédité de la couleur des yeux dans le Codex.","type":"textarea","min":30,"required":true},{"id":"q2","label":"Un membre demande un pelage rare pour son OC — comment évalues-tu la demande ?","type":"textarea","min":30,"required":true},{"id":"q3","label":"Comment tiens-tu un registre génétique à jour sur un serveur actif ?","type":"textarea","min":30,"required":true}]}]$j$::jsonb,1);
insert into recrutement.postes (categorie,groupe,nom,description,missions,anciennete,disponibilite,note_candidat,statut,places_total,places_dispo,questions,options,ordre) values ('staff',$s$narration$s$,$s$Staff Narration$s$,$s$Faire vivre le roleplay : tickets, événements et cohérence narrative.$s$,array[$s$Aider les membres en ticket pour le RP$s$,$s$Créer des événements role-play$s$,$s$S'assurer que les règles role-play sont appliquées$s$,$s$Créer des tâches dans le clan$s$]::text[],$s$1 à 2 mois sur le serveur$s$,$s$5h / semaine minimum$s$,$s$Les options sont facultatives : tu peux candidater au rôle sans en choisir.$s$,'ouvert',2,2,$j$[{"id":"q1","label":"Un membre vient en ticket avec une intrigue complexe — comment l'accompagnes-tu ?","type":"textarea","min":30,"required":true},{"id":"q2","label":"Un membre enfreint une règle RP en pleine scène — comment interviens-tu sans casser l’immersion ?","type":"textarea","min":30,"required":true},{"id":"q3","label":"Propose une idée d’événement role-play pour le serveur.","type":"textarea","min":30,"required":true},{"id":"q4","label":"Quelles tâches imagines-tu pour dynamiser la vie d’un clan ?","type":"textarea","min":30,"required":true}]$j$::jsonb,$j$[{"id":"pnj","nom":"Gestion PNJ","description":"Gestion et incarnation des PNJ de l'univers.","missions":["Gestion et incarnation des PNJ lors des interactions avec les membres","Création de nouveaux PNJ cohérents avec le lore et l'univers","Suivi des PNJ impliqués dans plusieurs fils narratifs simultanément"],"places_total":2,"places_dispo":2,"membres":[],"questions":[{"id":"q1","label":"Comment gères-tu un PNJ impliqué dans plusieurs fils narratifs actifs ?","type":"textarea","min":30,"required":true},{"id":"q2","label":"Crée un concept de PNJ secondaire pour le Clan de l'Ombre.","type":"textarea","min":30,"required":true},{"id":"q3","label":"Un PNJ que tu joues doit prendre une décision qui déplaira à certains membres — comment procèdes-tu ?","type":"textarea","min":30,"required":true}]}]$j$::jsonb,2);
update recrutement.formulaires set etapes = jsonb_set(etapes, '{1,description}', to_jsonb($s$Choisis ton équipe, puis les options qui t’intéressent.$s$::text)) where type = 'staff';
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Candidatures Staff$s$,$s$Que sont les options ?$s$,$s$Dans chaque équipe, des options facultatives existent (Régisseur·se de fiche et Généticien·ne chez les Guides, Gestion PNJ chez les Narrateurs). Elles ajoutent quelques questions, et tu es libre de ne pas en choisir.$s$,6);
